def run(_context):
    import json
    # Search for all drills
    print("=== ALL DRILLS ===")
    dr = mb.list_library_tools(contains="Drill")
    for t in dr:
        print(f"  idx={t['index']}: {t['description']} | dia={t['diameter_mm']:.4f}mm | flutes={t['flutes']}")

    # Also check for 1/4" flat endmill and 3/16" endmill
    print("\n=== SMALL FLAT END MILLS ===")
    for t in mb.list_library_tools(contains="Flat Endmill"):
        if t["diameter_mm"] and t["diameter_mm"] <= 10:
            print(f"  idx={t['index']}: {t['description']} | dia={t['diameter_mm']:.4f}mm | flutes={t['flutes']} | cr={t['corner_radius_mm']}")

    # Check for center drills
    print("\n=== CENTER DRILLS ===")
    for t in mb.list_library_tools(contains="Center"):
        print(f"  idx={t['index']}: {t['description']} | dia={t['diameter_mm']:.4f}mm")

    # Check for any 1/4" flat endmill
    print("\n=== 1/4 FLAT END MILLS ===")
    for t in mb.list_library_tools(contains="1/4"):
        if "Flat" in t["description"]:
            print(f"  idx={t['index']}: {t['description']} | dia={t['diameter_mm']:.4f}mm | flutes={t['flutes']} | cr={t['corner_radius_mm']}")

