def run(_context):
    import adsk.cam
    import adsk.core

    cam = mb.get_cam()
    setup = cam.setups.itemByName("Setup1")
    op = setup.operations.itemByName("Spot Drill")

    # Find all CadObjectParameterValue parameters
    print("=== CadObjectParameterValue PARAMS ===")
    for i in range(op.parameters.count):
        param = op.parameters.item(i)
        val = param.value
        if val and 'CadObjectParameterValue' in type(val).__name__:
            # Check the value
            try:
                v = val.value
                count = v.count if hasattr(v, 'count') else 'N/A'
                print(f"  {param.name}: count={count}")
                # List items if any
                if hasattr(v, 'count') and v.count > 0:
                    for j in range(v.count):
                        item = v.item(j)
                        print(f"    item[{j}]: {type(item).__name__}")
            except Exception as e:
                print(f"  {param.name}: error reading value: {e}")

    # Also check for any parameter that might be a selection
    print("\n=== CHECKING holeModel PARAMETER ===")
    for i in range(op.parameters.count):
        param = op.parameters.item(i)
        if param.name == "holeModel":
            print(f"  holeModel: expression={param.expression}, value_type={type(param.value).__name__}")
            if param.value:
                print(f"  value: {param.value.value}")

    # Let's also look at what the "useCheckSurface" param is
    print("\n=== CHECK useCheckSurface ===")
    for i in range(op.parameters.count):
        param = op.parameters.item(i)
        if param.name in ["useCheckSurface", "checkSurfaceSelectionSets"]:
            print(f"  {param.name}: expression={param.expression}")

